INSERT INTO academy_learning_categories(id,label,first_method,last_method) VALUES
  (1, 'Nature, Cosmos & Physical Observation', 1, 20),
  (2, 'Body, Art, Rhythm & Sensory Stimulation', 21, 40),
  (3, 'Intuition, Pattern Decoding & Cognitive Drills', 41, 60),
  (4, 'Lineage, Memory & Historical Continuity', 61, 75),
  (5, 'Critical Thinking, Sovereignty & Real-World Mastery', 76, 101)
INSERT INTO academy_learning_methods(id,category_id,title,original_text,activity) VALUES
  (1, 1, 'Stargazing & Constellations', 'Learn geometry, navigation, and seasonal tracking by mapping the night sky by eye.', 'Sketch three visible stars from a stationary viewing spot. Use a ruler to compare their angles on paper and repeat on another night.'),
  (2, 1, 'Lunar Cycles', 'Learn timekeeping, tides, and biological rhythms by tracking the moon''s phases over 28 days.', 'Use a printed moon-phase calendar or make a shadow model with a lamp and a ball. Label the visible phase on three dates and predict the next.'),
  (3, 1, 'Observing Snakes & Reptiles', 'Learn stealth, patience, and survival mechanics by studying how cold-blooded creatures conserve energy and strike.', 'Compare a photo or an official wildlife video of two reptiles. Mark observable signs of movement, shelter use, or heat-seeking without approaching or handling wildlife.'),
  (4, 1, 'Deep-Sea & Megafauna Biology', 'Stimulate awe and scale comprehension by studying massive creatures of the deep and fossil records.', 'Use a ruler and a consistent scale to draw the length of two sea animals on paper. Add a fossil measurement and explain which evidence is estimated.'),
  (5, 1, 'Nocturnal Bird & Animal Tracking', 'Sharpen night vision and hearing by identifying owls, ravens, and night creatures by sound alone.', 'Listen to two recorded bird calls. Mark the rhythm of each on paper, then match the calls to a field-guide recording. Live observation can be done from a familiar, lit spot.'),
  (6, 1, 'Apex Predator Behavior', 'Learn pack dynamics, territory, and leadership by studying lions and wolves in nature.', 'Watch two documentary clips of lions or wolves and tally when animals move together or alone. Decide which behaviors the footage supports.'),
  (7, 1, 'Livestock & Animal Husbandry', 'Learn responsibility, anatomy, and breeding cycles by raising and caring for farm animals.', 'Design one day''s care chart for a species using a published care guide. Where an animal''s keeper is present, record one real observation with their permission.'),
  (8, 1, 'Dark-Room & Night Navigation', 'Train spatial awareness and non-visual senses by navigating in complete darkness without artificial light.', 'Make a cardboard tabletop maze. With the room lit and your feet planted, close your eyes only while tracing the maze with one finger. Compare your first and second maps.'),
  (9, 1, 'Mineralogy & Crystal Lattices', 'Learn chemistry, light refraction, and structural geometry by examining raw quartz, salt, and gemstones.', 'Examine labeled specimens or photos of quartz and salt. Draw the faces you can see and make a model of one repeating shape with cubes or blocks.'),
  (10, 1, 'Botanical Distillation & Aromatics', 'Stimulate olfactory memory and chemistry by extracting oils and scents from raw herbs and resins.', 'Compare the scent of two familiar culinary herbs at room temperature, or compare their images if scents are unsuitable. Label your observations and draw a diagram of how a distillation apparatus separates vapor and liquid.'),
  (11, 1, 'Forestry & Tree Propagation', 'Learn long-term planning and ecology by planting, grafting, and tracking tree growth across seasons.', 'Mark the height and new leaves of a potted plant. Compare it with a second plant while keeping the recording schedule constant.'),
  (12, 1, 'Weather & Storm Mechanics', 'Learn physics, barometric pressure, and acoustics by measuring lightning distance and cloud formations.', 'Use archived storm timestamps or a simulated flash-and-sound delay. Estimate distance on paper and explain why a lightning storm is an indoor observation activity.'),
  (13, 1, 'Hydrology & Water Currents', 'Learn fluid dynamics by building dams, channels, and water wheels in creeks and rivers.', 'Build two removable channels in a shallow tray. Change one slope with a folded towel underneath, then compare where a spoonful of water travels.'),
  (14, 1, 'Salt Crystallization & Preservation', 'Learn chemistry and food science by curing meats, fermenting, and growing salt crystals.', 'Dissolve table salt in water and observe the residue after a small, labeled sample evaporates. Compare the crystal pattern with dry salt. Use published examples to discuss food preservation.'),
  (15, 1, 'Fire Craft & Thermodynamics', 'Learn combustion, airflow, and heat transfer by building fires without matches or lighters.', 'Compare how long two cups of warm tap water stay warm with and without a cardboard sleeve. Draw a heat-flow diagram for each cup.'),
  (16, 1, 'Osteology & Skeletal Anatomy', 'Learn structural engineering by assembling and identifying animal bones and skulls.', 'Build a paper skeleton or examine a museum scan. Label a joint and test its range of motion with two cardboard pieces joined by a paper fastener.'),
  (17, 1, 'Circulatory & Pulse Mechanics', 'Learn biology and stress regulation by monitoring heart rate, breath, and blood flow under exertion.', 'Use a diagram of circulation and count your own resting pulse if comfortable. Plot three resting observations and describe why measurements can differ.'),
  (18, 1, 'Soil Composition & Earthwork', 'Learn agriculture and construction by testing clay, sand, and loam with bare hands.', 'Compare equal spoons of clean potting soil, sand, and clay in trays. Add the same amount of water to each and record runoff and texture.'),
  (19, 1, 'Seed Saving & Heirloom Gardening', 'Learn genetics and self-reliance by harvesting seeds from fruit and planting next year''s crop.', 'Collect, label, and count seeds from a familiar garden crop. Place a few on a damp paper towel and log which sprout.'),
  (20, 1, 'Optics & Light Prisms', 'Learn wave physics by splitting white light into full color spectrums using water and glass.', 'Use a prism in indirect daylight or a clear glass of water by a window to cast a spectrum onto white paper. Sketch the order of colors.'),
  (21, 2, 'Full-Body Movement & Dance', 'Stimulate coordination and kinesthetic memory by learning complex rhythmic footwork.', 'Choose three seated or standing movements and pair them with a four-count rhythm. Change one move, then demonstrate your new sequence.'),
  (22, 2, 'Percussion & Poly-Rhythms', 'Train bilateral brain synchronization by drumming two different beats simultaneously with left and right hands.', 'Tap a steady beat with one hand and a slower beat with the other on a soft surface. Mark the points where the two taps align.'),
  (23, 2, 'Acoustic Resonance & Volume', 'Learn sound waves and vibration by testing how different frequencies shake physical objects.', 'Place grains of rice on a stretched paper membrane and hum gently near it. Compare the grains'' movement at two comfortable pitches.'),
  (24, 2, 'Stringed Instrument Tuning', 'Train pitch recognition and tension physics by tuning strings purely by ear.', 'Pluck two rubber bands with different tension at low volume. Compare the pitches by ear and record which arrangement sounds higher.'),
  (25, 2, 'Communal Feast Planning', 'Learn math, logistics, and hospitality by budgeting, cooking, and serving a meal for a large group.', 'Plan a six-person meal on paper. Scale one recipe to a second guest count, make a shopping list, and reserve a serving for an unexpected guest.'),
  (26, 2, 'Fermentation & Culinary Chemistry', 'Learn microbiology by making bread, vinegar, or fermented drinks from scratch.', 'Observe a small portion of bread dough before and after rising using a familiar kitchen recipe. Sketch the change in volume and role of gas.'),
  (27, 2, 'Metallurgy & Silversmithing', 'Learn heat treatment and precision handwork by hammering, melting, and shaping metal.', 'Compare the shape and stiffness of aluminum foil before and after folding. Sketch the fold pattern and compare it with a labeled metalworking process diagram.'),
  (28, 2, 'Natural Pigment & Dye Making', 'Learn art history and chemistry by crushing minerals, berries, and charcoal into paint.', 'Make color swatches from kitchen-safe food coloring or familiar edible plant materials. Let them dry and compare how water changes their spread.'),
  (29, 2, 'Incense & Smoke Blending', 'Stimulate focus and sensory anchoring by pairing specific scents with specific study subjects.', 'Compare two unburned familiar scents, or look at two labeled scent illustrations. Pair each with a study cue and see which cue you recall later.'),
  (30, 2, 'Physical Endurance & Vow Discipline', 'Build willpower by committing to a strict physical rule or restraint for a set period.', 'Choose one comfortable repeated action for a short timed interval, with permission to pause. Keep a tally and compare effort at the beginning and end.'),
  (31, 2, 'Calligraphy & Permanent Mark-Making', 'Train fine motor control by carving or inking permanent glyphs onto wood, leather, or stone.', 'Write the same large letter on paper using a marker and chalk. Compare stroke angles, pressure, and legibility.'),
  (32, 2, 'Bodyweight Mechanics & Calisthenics', 'Learn leverage and center of gravity without gym machines.', 'Balance a ruler over an eraser at two points. Use the model to explain why a body''s center of gravity matters during a movement.'),
  (33, 2, 'Martial Grappling & Contact Drills', 'Stimulate reflexes and composure under physical pressure through wrestling and sparring.', 'With a partner, mirror three slow hand movements without contact. Switch leaders and discuss what kept both people in control.'),
  (34, 2, 'Comedy, Timing & Satire', 'Train rapid pattern recognition and social awareness by writing and delivering jokes.', 'Write one setup with two different punchlines. Try each with a willing partner and ask which words produced the timing.'),
  (35, 2, 'Roleplay & Dramatic Enactment', 'Lock in historical or ethical lessons by acting out scenarios from multiple perspectives.', 'Use a source excerpt to assign two perspectives. Role-play a decision and then switch sides, keeping the quotation available.'),
  (36, 2, 'Rhyme, Cadence & Spoken Word', 'Accelerate memory retention by turning complex facts into rhythmic poetry and songs.', 'Turn three source facts into a four-line rhythm. Recite it later and check the facts against the original.'),
  (37, 2, 'Woodcarving & Stone Sculpting', 'Train 3D spatial visualization by removing material to reveal a shape inside a raw block.', 'Sculpt the same object in clay from two viewing angles. Change one contour and explain its effect on the shape.'),
  (38, 2, 'Mask Making & Persona Exploration', 'Learn psychology and theater by crafting masks to study how appearance alters behavior.', 'Draw two removable paper masks and write a line of dialogue for each persona. Ask how the image changes the perceived tone.'),
  (39, 2, 'Heraldry & Visual Symbol Design', 'Learn graphic communication by designing flags and emblems that convey meaning without words.', 'Choose three values and draw a flag using only color and shape. Ask a partner what they infer before you explain.'),
  (40, 2, 'Stillness & Sensory Deprivation', 'Train mental control by sitting completely still in silence for 30 minutes without fidgeting.', 'Try a voluntary two-minute quiet pause in a comfortable, lit space. Notice one sound and one bodily sensation, then compare notes.'),
  (41, 3, 'Dream Journaling & Recall', 'Train subconscious retrieval by writing down every dream immediately upon waking.', 'On waking, privately record any dream detail you choose to remember. Track the number of details across three mornings and keep the content private.'),
  (42, 3, 'Symbol & Metaphor Decoding', 'Sharpen analytical reading by translating visual dream symbols into concrete real-world parallels.', 'Pick a symbol in a story or supplied image. Give two possible readings, each supported by a visible or textual detail.'),
  (43, 3, 'Deep Visualization & Mental Modeling', 'Train the mind''s eye to build, rotate, and test mechanical parts entirely in thought.', 'Visualize turning a block a quarter turn. Make or use a paper model to check which face would end up on top.'),
  (44, 3, 'Perspective Shifting (Bird''s-Eye View)', 'Solve stuck problems by mentally stepping outside the room and viewing the situation from above.', 'Draw a familiar tabletop arrangement from above and from eye level. Compare which relationships become easier to see.'),
  (45, 3, 'Cold Reading & Micro-Expression Observation', 'Learn human behavior by watching posture, eye movement, and tone without relying on words.', 'Observe a silent acted clip and record only visible movements first. With sound restored, check which guesses about emotion or intent held up.'),
  (46, 3, 'Probability & Game Theory (Dice & Cards)', 'Learn statistics, risk management, and odds calculation through live games.', 'Predict how often a six-sided die will land on one chosen face in 24 rolls. Run the trials and compare counts with your prediction.'),
  (47, 3, 'Binary & Logic Gate Puzzles', 'Train deterministic yes/no reasoning using physical switches and truth tables.', 'Use two yes/no cards as inputs. Complete a truth table for AND and OR, then ask a partner to verify every row.'),
  (48, 3, 'Controlled Experimentation (A/B Testing)', 'Learn the scientific method by changing one single variable at a time and recording the result.', 'Fold two paper gliders, changing only one dimension. Make equal trials in the same space and record distances.'),
  (49, 3, 'Gut-Check & Rapid Decision Drills', 'Train pattern-based intuition by making split-second choices under time limits, then reviewing outcomes.', 'Use a quick sorting game with ambiguous sample cards. Mark your initial rule and later review the mistakes one at a time.'),
  (50, 3, 'Intermittent Fasting & Metabolic Control', 'Learn how blood sugar and hunger affect mental sharpness and focus.', 'Graph energy ratings from a supplied fictional meal-and-activity log. Compare patterns and list other explanations without changing anyone''s meals.'),
  (51, 3, 'Night-Watch Focus Drills', 'Train alertness and discipline during late-night hours when distractions disappear.', 'Plan two mock observation shifts during normal waking hours. Compare alertness tallies and identify one change to the schedule.'),
  (52, 3, 'Phonetic Sound Breakdown', 'Master spelling and pronunciation by stripping words down to raw vowel and consonant sounds.', 'Choose a word and say it slowly. Count sounds independently of letters and compare with a dictionary pronunciation.'),
  (53, 3, 'Riddle Solving & Lateral Thinking', 'Break rigid thought patterns by solving and writing multi-layered riddles.', 'Solve a short riddle, then change one clue and test it on a willing partner. Keep both versions for comparison.'),
  (54, 3, 'Peripheral Vision & Full-Room Scanning', 'Train situational awareness by taking in an entire room in a single glance and recalling every detail.', 'From a fixed, comfortable spot, note which of two colored cards enters side view first. Repeat and compare without claiming a medical measurement.'),
  (55, 3, 'Motive & Subtext Analysis', 'Learn discernment by identifying what people leave unsaid in speeches, ads, and contracts.', 'Read a short advertisement. Underline its explicit promise and list what information you''d need to judge the implied benefit.'),
  (56, 3, 'Timed Silence in Conversation', 'Learn negotiation and listening by pausing five full seconds before answering any question.', 'With a willing partner, try one question with an ordinary pause and one with a longer pause. Compare which answer addressed the question more directly.'),
  (57, 3, 'Non-Verbal Communication Drills', 'Convey instructions, warnings, or emotions to a partner without speaking a single word.', 'Send a two-step instruction using gesture during a tabletop task. Ask your partner to repeat the meaning before following it.'),
  (58, 3, 'Reverse-Engineering Illusions & Magic Tricks', 'Train skepticism and mechanical curiosity by figuring out how sleight-of-hand works.', 'Watch a public demonstration of an optical illusion. Draw what viewers see and diagram one mechanism that could explain it.'),
  (59, 3, 'Shadow & Sundial Geometry', 'Learn trigonometry and earth rotation by tracking shadow lengths throughout the day.', 'Mark the shadow of a fixed stick at three times. Measure the lengths and explain which direction or timing information came from the pattern.'),
  (60, 3, 'Tactile Object Identification (Blindfolded)', 'Heighten touch sensitivity by identifying tools, coins, and materials blindfolded.', 'Identify three smooth, clean objects by touch inside a bag while seated. Verify the guesses by sight and tally which features helped.'),
  (61, 4, 'Genealogy & Family Tree Mapping', 'Learn history and genetics by tracing your bloodline back five or more generations.', 'Build a three-generation diagram from fictional records or family records you have permission to use. Mark one agreement and one conflict between sources.'),
  (62, 4, 'Graveyard & Monument Rubbings', 'Learn local history and typography by visiting historic cemeteries and recording dates and epitaphs.', 'Use photos or public transcriptions of two monuments. Compare a date or letterform and cite the site without touching the stone.'),
  (63, 4, 'Building Physical Landmarks & Cairns', 'Anchor lessons in the physical world by stacking stone markers tied to specific milestones.', 'Build a temporary marker with blocks on a tray. Map its location and have a partner find it using your directions.'),
  (64, 4, 'Oral Biography Interviews', 'Preserve living history by recording long-form interviews with elders before their stories are lost.', 'Ask a willing adult to describe a remembered tool or event. Agree on recording and sharing before interviewing and confirm your summary with them.'),
  (65, 4, 'Grief Processing & Emotional Release', 'Learn emotional resilience through structured writing, music, and honest lamentation.', 'Use a fictional character or a private reflection to write three lines about a loss, one memory, and one source of support. The learner chooses whether to share.'),
  (66, 4, 'Botanical Preservation & Herbarium Pressing', 'Learn taxonomy by drying, pressing, and cataloging native plants and spices.', 'Press a common garden leaf you have permission to collect or use a photo. Label date, location, and observable traits.'),
  (67, 4, 'Architecture & Underground Construction', 'Learn structural load, insulation, and excavation by studying caves, cellars, and stone vaults.', 'Build two cardboard cross-sections of an underground room and test how they distribute identical small weights. Compare sketches with a building diagram.'),
  (68, 4, 'Eulogy & Legacy Writing', 'Clarify life priorities by writing a summary of what a person stood for and built.', 'Write a short legacy paragraph for a historical figure or fictional character. Cite one action that supports the trait you chose.'),
  (69, 4, 'Spoken Blessing & Affirmation Drills', 'Practice leadership by articulating specific strengths and potential you see in others.', 'Offer a willing partner one specific affirmation tied to something you observed. Ask whether the words describe their achievement accurately.'),
  (70, 4, 'Primary Source Historical Immersion', 'Bypass modern textbooks by reading original letters, diaries, and newspapers from the era.', 'Read a letter, diary entry, or newspaper excerpt from an archive. Highlight a claim the author saw firsthand and another they heard from someone else.'),
  (71, 4, 'Cross-Generational Mentorship', 'Pair the oldest and youngest learners together to transfer practical skills directly.', 'Ask a willing mentor to show one small skill. Repeat it and let the mentor check one observable step, then exchange roles.'),
  (72, 4, 'Sleep Architecture & Recovery Tracking', 'Learn neuroscience by tracking sleep cycles, dreams, and waking energy levels.', 'Graph bedtimes, waking times, and energy from a fictional seven-day sleep log. Identify the limits of what the log can tell you about sleep stages.'),
  (73, 4, 'Composting & Decomposition Cycles', 'Learn biology by turning organic waste into rich topsoil.', 'Compare a photo timeline of compost with an annotated list of inputs. Use a model or supervised garden bin to track one decomposition variable.'),
  (74, 4, 'Tool Restoration & Heirloom Repair', 'Learn mechanical engineering by taking broken vintage tools apart, cleaning them, and restoring them to working order.', 'Take apart and reassemble a low-risk object like a hand-operated clamp or toy, with consent. Photograph each step and verify the restored motion.'),
  (75, 4, 'Memory Palace & Oral Storytelling', 'Memorize massive sequences of facts by anchoring them to physical locations and vivid stories.', 'Assign five facts to landmarks in an imagined familiar room. Recall them in order and then in reverse, checking against the list.'),
  (76, 5, 'Socratic Interrogation ("Why?" Five Times)', 'Get to the root cause of any problem by asking "why" five layers deep.', 'Pick a simple failure such as a box tipping over. Ask why, test the first answer against what you can observe, and follow a second cause when warranted.'),
  (77, 5, 'Hands-On Verification & Skepticism', 'Never take an expert''s word blindly; test claims physically to confirm they hold up.', 'Predict whether a folded or flat strip of paper holds more coins across the same span. Test fairly and compare the results with your prediction.'),
  (78, 5, 'Fact-Checking & Source Auditing', 'Compare two conflicting news reports or historical accounts side-by-side to spot omissions.', 'Compare two articles about one event. Underline one agreement and one disagreement, then trace each disputed claim to its earliest cited record.'),
  (79, 5, 'Cross-Cultural Philosophy Debate', 'Read opposing worldviews (Greek, Indigenous, Eastern, Biblical) and argue both sides accurately.', 'Choose two published texts about a common ethical question. Summarize each so a reader can locate the supporting passage before presenting your own view.'),
  (80, 5, 'Comparative Language & Root Etymology', 'Learn English deeply by tracing words back to Hebrew, Greek, Latin, and Old English roots.', 'Use dictionary and concordance entries to compare one word''s earliest recorded sense with its current usage. Record the language and source for each step.'),
  (81, 5, 'Financial Literacy & Ledger Accounting', 'Learn double-entry bookkeeping, profit/loss, and asset building from scratch.', 'Record a fictional sale and expense in a two-column ledger. Reconcile the closing balance and show how to find a deliberate error.'),
  (82, 5, 'Mandatory Rest & Digital Detox', 'Protect mental clarity by shutting off all screens and work for 24 straight hours every week.', 'Choose a voluntary short offline interval with an accessible alternative. Before and after, note which task you could focus on or recall.'),
  (83, 5, 'Ethical Boundaries & Righteous Pushback', 'Practice standing firm and speaking up clearly when witnessing bullying or fraud.', 'Role-play how to raise a fictional concern about bullying. Write a clear statement of what happened, whom you would ask for help, and what you would protect.'),
  (84, 5, 'Civil Disobedience & Case Studies', 'Study historical moments where individuals refused unjust orders to protect innocent people.', 'Compare two documented historical actions taken against an unjust rule. Record the rule, what was done, and what consequences were documented.'),
  (85, 5, 'Debate & Public Oratory', 'Build confidence by delivering persuasive speeches without notes.', 'Give a one-minute sourced argument to a willing listener. Ask them to repeat your main claim and identify one part that needed evidence.'),
  (86, 5, 'Cultural Immersion & Hospitality', 'Learn geography and anthropology by cooking meals and learning customs from unfamiliar cultures.', 'Use a source from the culture you study to plan a fictional welcome meal or visit. Explain the reason for one practice in the source''s own terms.'),
  (87, 5, 'Conflict Resolution & Mediation', 'Step into a dispute between two sides and negotiate a fair, peaceful outcome.', 'Use a fictional dispute. Let each participant restate the other person''s concern and write one verifiable agreement.'),
  (88, 5, 'Nutrition & Elimination Testing', 'Learn how specific foods affect energy, focus, and inflammation in your own body.', 'Compare the ingredient labels of two example foods and chart their differences. Use a fictional observations log to discuss confounding without directing anyone to restrict food.'),
  (89, 5, 'Self-Directed Scheduling', 'Eliminate external bells and rigid clocks; learn to manage projects by milestones rather than hours.', 'Set milestones for a short independent project. Watch which milestone slips and write one change that would improve the next plan.'),
  (90, 5, 'Outdoor & Off-Grid Field Classrooms', 'Conduct lessons in woods, workshops, kitchens, and town squares instead of classrooms.', 'Draw a safe outdoor classroom map for a familiar supervised place. Choose a station for observing, building, or explaining, and conduct a short session there.'),
  (91, 5, 'First Aid, Anatomy & Self-Care', 'Learn wound care, splinting, nutrition, and physical maintenance.', 'Use a first-aid training resource and a doll or practice kit to rehearse calling for help and identifying a hazard. Check the steps with a qualified instructor.'),
  (92, 5, 'Team Covenant & Trust Exercises', 'Build unbreakable loyalty through high-stakes group challenges (ropes courses, navigation, building).', 'Plan a cooperative tabletop building challenge in which every person can opt out. Rotate roles and compare which agreements improved teamwork.'),
  (93, 5, 'Animal Behavior & Body Language Training', 'Learn communication without words by training dogs, horses, or birds using patience and consistency.', 'Observe a consenting animal caretaker and an animal from a comfortable distance. Describe body posture before making a guess about what the animal wants.'),
  (94, 5, 'Sacred Geometry & Compass Drafting', 'Learn math visually by constructing geometric shapes using only a straightedge and compass.', 'Construct a circle, hexagon, and perpendicular bisector with a pencil compass and straightedge. Explain which lengths must be equal.'),
  (95, 5, 'Play-Based Game Design', 'Master rules, balance, and psychology by inventing a playable board, card, or yard game from scratch.', 'Make a paper prototype of a game with three rules. Play one round with a partner and change only one rule before a second round.'),
  (96, 5, 'Solo Wilderness Survival', 'Build total self-reliance by spending 24–48 hours alone outdoors with minimal gear.', 'Plan a fictional overnight route on a map. Identify shelter, water, time, and communication checkpoints, then rehearse the plan as a supervised daytime exercise.'),
  (97, 5, 'Daily Stream-of-Consciousness Writing', 'Clear mental clutter and spark creativity by writing three pages every morning without editing.', 'Write freely for five minutes and underline a thought you want to revisit. The learner chooses whether the writing stays private.'),
  (98, 5, 'Satire & Irony Analysis', 'Learn rhetorical mastery by dissecting how humor and exaggeration expose hypocrisy.', 'Choose a short satire excerpt and mark the literal claim and the exaggerated claim. Explain what the gap exposes.'),
  (99, 5, 'Instant Conflict Reset', 'Practice letting go of petty grudges immediately so mental energy stays focused on the mission.', 'Practice a voluntary pause and reset in a fictional disagreement. State one thing you''d do differently and one issue that still needs repair.'),
  (100, 5, 'Community Service & Direct Aid', 'Learn practical compassion by solving real problems for neighbors, elders, or people on the street.', 'Ask a partner or local group about one small need they want help with. Agree on a useful action and let the recipient describe whether it helped.'),
  (101, 5, 'Self-Mastery & Independent Teaching', 'Prove true mastery of any subject by teaching it clearly to a beginner without using notes.', 'Choose a method you have practiced. Teach one step to a beginner, let them demonstrate it, and revise your explanation based on what they do.')
INSERT INTO academy_learning_channels(id,title,original_text) VALUES
  (1, 'Sensory Hook (Stimulate)', 'Touch, smell, hear, or see the physical object first before reading a single word about it.'),
  (2, 'Pattern Decode (Analyze)', 'Strip away labels and ask: What is it made of? How does it work? What happens if I reverse it?'),
  (3, 'Physical Application (Build/Test)', 'Use your hands to build, repair, cook, map, or test it in real life.'),
  (4, 'Moral & Root Check (Discern)', 'Ask: Does this protect life and truth, or is it a con?'),
  (5, 'Teach Back (Mastery)', 'Explain or demonstrate what you just did to someone else in plain, simple words.')
INSERT INTO library_catalog (id,title,author,classification_code,r2_object_key,material_type,public_url) VALUES
  ('101-learning-methods','101 Hands-On Learning Methods','Tabor Academy','TA.LAB.101',NULL,'Learning collection','/tabor-academy/institution/learning-methods/'),
